export const getApiV3DepthRoute = createRoute({
  method: 'get',
  path: '/api/v3/depth',
  tags: ['Market'],
  summary: 'Order Book',
  description:
    '| Limit               | Weight(IP)  |\n|---------------------|-------------|\n| 1-100               | 5           |\n| 101-500             | 25          |\n| 501-1000            | 50          |\n| 1001-5000           | 250         |',
  request: {
    query: z.object({
      symbol: SymbolParamsSchema,
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().max(5000),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'If limit > 5000, then the response will truncate to 5000',
            schema: { type: 'integer', format: 'int32', default: 100, maximum: 5000, example: 100 },
            required: false,
          },
          example: 100,
        }),
    }),
  },
  responses: {
    200: {
      description: 'Order book',
      content: {
        'application/json': {
          schema: z
            .object({
              lastUpdateId: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({ type: 'integer', format: 'int64' }),
              bids: z.array(z.array(z.string())),
              asks: z.array(z.array(z.string())),
            })
            .openapi({ required: ['lastUpdateId', 'bids', 'asks'] }),
          example: {
            lastUpdateId: 1027024,
            bids: [['4.00000000', '431.00000000']],
            asks: [['4.00000200', '12.00000000']],
          },
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
  },
})

