export const getApiV3KlinesRoute = createRoute({
  method: 'get',
  path: '/api/v3/klines',
  tags: ['Market'],
  summary: 'Kline/Candlestick Data',
  description:
    'Kline/candlestick bars for a symbol.\nKlines are uniquely identified by their open time.\n\n- If `startTime` and `endTime` are not sent, the most recent klines are returned.\n\nWeight(IP): 2',
  request: {
    query: z.object({
      symbol: SymbolParamsSchema,
      interval: z
        .enum([
          '1s',
          '1m',
          '3m',
          '5m',
          '15m',
          '30m',
          '1h',
          '2h',
          '4h',
          '6h',
          '8h',
          '12h',
          '1d',
          '3d',
          '1w',
          '1M',
        ])
        .openapi({
          param: {
            name: 'interval',
            in: 'query',
            required: true,
            description: 'kline intervals',
            schema: {
              type: 'string',
              enum: [
                '1s',
                '1m',
                '3m',
                '5m',
                '15m',
                '30m',
                '1h',
                '2h',
                '4h',
                '6h',
                '8h',
                '12h',
                '1d',
                '3d',
                '1w',
                '1M',
              ],
              example: '"1m"',
            },
          },
          example: '"1m"',
        }),
      startTime: StartTimeParamsSchema,
      endTime: EndTimeParamsSchema,
      timeZone: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'timeZone',
            in: 'query',
            required: false,
            description: 'Default: 0 (UTC)',
            schema: { type: 'string' },
          },
        }),
      limit: LimitParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Kline data',
      content: {
        'application/json': {
          schema: z.array(
            z
              .array(
                (() => {
                  const Schema = z.xor([
                    z
                      .preprocess(
                        (val) =>
                          typeof val === 'number' && Number.isSafeInteger(val)
                            ? BigInt(val)
                            : typeof val === 'string' && /^-?\d+$/.test(val)
                              ? BigInt(val)
                              : val,
                        z.int64(),
                      )
                      .openapi({ type: 'integer', format: 'int64' }),
                    z.string(),
                  ])
                  return z.preprocess((val: z.input<typeof Schema>, ctx) => {
                    ;((ctx) => {
                      const val = ctx.value
                      if (Array.isArray(val)) {
                        if (val.length < 12) {
                          ctx.issues.push({ ...{ code: 'custom' }, input: val })
                        }
                        if (val.length > 12) {
                          ctx.issues.push({ ...{ code: 'custom' }, input: val })
                        }
                      }
                    })(ctx)
                    return val
                  }, Schema)
                })().openapi({ minItems: 12, maxItems: 12 }),
              )
              .openapi({
                example: [
                  1499040000000,
                  '0.01634790',
                  '0.80000000',
                  '0.01575800',
                  '0.01577100',
                  '148976.11427815',
                  1499644799999,
                  '2434.19055334',
                  308,
                  '1756.87402397',
                  '28.46694368',
                  '17928899.62484339',
                ],
              }),
          ),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
  },
})

