          param: {
            name: 'cancelReplaceMode',
            in: 'query',
            required: true,
            description:
              '- `STOP_ON_FAILURE` If the cancel request fails, the new order placement will not be attempted.\n- `ALLOW_FAILURES` If new order placement will be attempted even if cancel request fails.',
            schema: { type: 'string', example: 'STOP_ON_FAILURE' },
          },
          example: 'STOP_ON_FAILURE',
