                'price',
                'origQty',
                'executedQty',
                'cummulativeQuoteQty',
                'status',
                'timeInForce',
                'type',
                'side',
                'workingTime',
                'fills',
                'workingFloor',
                'selfTradePreventionMode',
                'usedSor',
