export const getSapiV1CapitalConfigGetallRoute = createRoute({
  method: 'get',
  path: '/sapi/v1/capital/config/getall',
  tags: ['Wallet'],
  summary: "All Coins' Information (USER_DATA)",
  description:
    'Get information of coins (available for deposit and withdraw) for user.\n\nWeight(IP): 10',
  request: {
    query: z.object({
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'All coins details information',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                coin: z.string().openapi({ example: 'BTC' }),
                depositAllEnable: z.boolean(),
                free: z.string().openapi({ example: '0.00000000' }),
                freeze: z.string().openapi({ example: '0.00000000' }),
                ipoable: z.string().openapi({ example: '0.00000000' }),
                ipoing: z.string().openapi({ example: '0.00000000' }),
                isLegalMoney: z.boolean().openapi({ example: false }),
                locked: z.string().openapi({ example: '0.00000000' }),
                name: z.string().openapi({ example: 'Bitcoin' }),
                networkList: z.array(
                  z
                    .object({
                      addressRegex: z.string().openapi({ example: '^(bnb1)[0-9a-z]{38}$' }),
                      coin: z.string().openapi({ example: 'BTC' }),
                      depositDesc: z
                        .string()
                        .openapi({
                          example: 'Wallet Maintenance, Deposit Suspended',
                          description: 'shown only when "depositEnable" is false.',
                        }),
                      depositEnable: z.boolean().openapi({ example: false }),
                      isDefault: z.boolean().openapi({ example: false }),
                      memoRegex: z.string().openapi({ example: '^[0-9A-Za-z\\-_]{1,120}$' }),
                      minConfirm: z
                        .preprocess(
                          (val) =>
                            typeof val === 'number' && Number.isSafeInteger(val)
                              ? BigInt(val)
                              : typeof val === 'string' && /^-?\d+$/.test(val)
                                ? BigInt(val)
                                : val,
                          z.int64(),
                        )
                        .openapi({
                          type: 'integer',
                          format: 'int64',
                          example: 1,
                          description: 'min number for balance confirmation.',
                        }),
                      name: z.string().openapi({ example: 'BEP2' }),
                      network: z.string().openapi({ example: 'ETH' }),
                      specialTips: z
                        .string()
                        .openapi({
                          example:
                            'Both a MEMO and an Address are required to successfully deposit your BEP2-BTCB tokens to Binance.',
                        }),
                      unLockConfirm: z
                        .preprocess(
                          (val) =>
                            typeof val === 'number' && Number.isSafeInteger(val)
                              ? BigInt(val)
                              : typeof val === 'string' && /^-?\d+$/.test(val)
                                ? BigInt(val)
                                : val,
                          z.int64(),
                        )
                        .openapi({
                          type: 'integer',
                          format: 'int64',
                          example: 0,
                          description: 'confirmation number for balance unlock.',
                        }),
                      withdrawDesc: z
                        .string()
                        .openapi({
                          example: 'Wallet Maintenance, Withdrawal Suspended',
                          description: 'shown only when "withdrawEnable" is false',
                        }),
                      withdrawEnable: z.boolean().openapi({ example: false }),
                      withdrawFee: z.string().openapi({ example: '0.00000220' }),
                      withdrawIntegerMultiple: z.string().openapi({ example: '0.00000001' }),
                      withdrawMax: z.string().openapi({ example: '9999999999.99999999' }),
                      withdrawMin: z.string().openapi({ example: '0.00000440' }),
                      sameAddress: z.boolean(),
                    })
                    .openapi({
                      required: [
                        'addressRegex',
                        'coin',
                        'depositDesc',
                        'depositEnable',
                        'isDefault',
                        'memoRegex',
                        'minConfirm',
                        'name',
                        'network',
                        'specialTips',
                        'unLockConfirm',
                        'withdrawDesc',
                        'withdrawEnable',
                        'withdrawFee',
                        'withdrawIntegerMultiple',
                        'withdrawMax',
                        'withdrawMin',
                        'sameAddress',
                      ],
                    }),
                ),
                storage: z.string().openapi({ example: '0.00000000' }),
                trading: z.boolean(),
                withdrawAllEnable: z.boolean(),
                withdrawing: z.string().openapi({ example: '0.00000000' }),
              })
              .openapi({
                required: [
                  'coin',
                  'depositAllEnable',
                  'free',
                  'freeze',
                  'ipoable',
                  'ipoing',
                  'isLegalMoney',
                  'locked',
                  'name',
                  'networkList',
                  'storage',
                  'trading',
                  'withdrawAllEnable',
                  'withdrawing',
                ],
              }),
          ),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

export const getSapiV1AccountSnapshotRoute = createRoute({
  method: 'get',
  path: '/sapi/v1/accountSnapshot',
  tags: ['Wallet'],
  summary: 'Daily Account Snapshot (USER_DATA)',
  description:
    '- The query time period must be less than 30 days\n- Support query within the last one month only\n- If startTimeand endTime not sent, return records of the last 7 days by default\n\nWeight(IP): 2400',
  request: {
    query: z.object({
      type: z
        .enum(['SPOT', 'MARGIN', 'FUTURES'])
        .openapi({
          param: {
            name: 'type',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['SPOT', 'MARGIN', 'FUTURES'] },
          },
        }),
      startTime: StartTimeParamsSchema,
      endTime: EndTimeParamsSchema,
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(7).max(30),
        )
        .default(7)
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            schema: { type: 'integer', format: 'int32', default: 7, minimum: 7, maximum: 30 },
            required: false,
          },
        }),
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Account Snapshot',
      content: {
        'application/json': {
          schema: z.xor([SnapshotSpotSchema, SnapshotMarginSchema, SnapshotFuturesSchema]),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

