export const postSapiV1CapitalWithdrawApplyRoute = createRoute({
  method: 'post',
  path: '/sapi/v1/capital/withdraw/apply',
  tags: ['Wallet'],
  summary: 'Withdraw (USER_DATA)',
  description:
    'Submit a withdraw request.\n\n- If `network` not send, return with default network of the coin.\n- You can get `network` and `isDefault` in `networkList` of a coin in the response of `Get /sapi/v1/capital/config/getall (HMAC SHA256)`.\n\nWeight(IP): 1',
  request: {
    query: z.object({
      coin: CoinParamsSchema,
      withdrawOrderId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'withdrawOrderId',
            in: 'query',
            description: 'Client id for withdraw',
            schema: { type: 'string' },
            required: false,
          },
        }),
      network: NetworkParamsSchema,
      address: z
        .string()
        .openapi({
          param: { name: 'address', in: 'query', required: true, schema: { type: 'string' } },
        }),
      addressTag: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'addressTag',
            in: 'query',
            description: 'Secondary address identifier for coins like XRP,XMR etc.',
            schema: { type: 'string' },
            required: false,
          },
        }),
      amount: AmountParamsSchema,
      transactionFeeFlag: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'transactionFeeFlag',
            in: 'query',
            description:
              'When making internal transfer\n- `true` ->  returning the fee to the destination account;\n- `false` -> returning the fee back to the departure account.',
            schema: { type: 'boolean', default: false },
            required: false,
          },
        }),
      name: z
        .string()
        .exactOptional()
        .openapi({
          param: { name: 'name', in: 'query', schema: { type: 'string' }, required: false },
        }),
      walletType: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'walletType',
            in: 'query',
            description:
              'The wallet type for withdraw，0-Spot wallet, 1- Funding wallet. Default is Spot wallet',
            schema: { type: 'integer', format: 'int32' },
            required: false,
          },
        }),
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Transafer Id',
      content: {
        'application/json': {
          schema: z
            .object({ id: z.string().openapi({ example: '7213fea8e94b4a5593d507237e5a555b' }) })
            .openapi({ required: ['id'] }),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

export const getSapiV1CapitalDepositHisrecRoute = createRoute({
  method: 'get',
  path: '/sapi/v1/capital/deposit/hisrec',
  tags: ['Wallet'],
  summary: 'Deposit History(supporting network) (USER_DATA)',
  description:
    'Fetch deposit history.\n\n- Please notice the default `startTime` and `endTime` to make sure that time interval is within 0-90 days.\n- If both `startTime` and `endTime` are sent, time between `startTime` and `endTime` must be less than 90 days.\n\nWeight(IP): 1',
  request: {
    query: z.object({
      coin: OptionalCoinParamsSchema,
      status: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'status',
            in: 'query',
            description: '* `0` - pending\n* `6` - credited but cannot withdraw\n* `1` - success',
            schema: { type: 'integer', format: 'int32' },
            required: false,
          },
        }),
      startTime: StartTimeParamsSchema,
      endTime: EndTimeParamsSchema,
      offset: OffsetParamsSchema,
      limit: LimitParamsSchema,
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'List of deposits',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                amount: z.string().openapi({ example: '0.00999800' }),
                coin: z.string().openapi({ example: 'PAXG' }),
                network: z.string().openapi({ example: 'ETH' }),
                status: z.int32().openapi({ example: 1 }),
                address: z
                  .string()
                  .openapi({ example: '0x788cabe9236ce061e5a892e1a59395a81fc8d62c' }),
                addressTag: z.string().openapi({ example: '' }),
                txId: z
                  .string()
                  .openapi({
                    example: '0xaad4654a3234aa6118af9b4b335f5ae81c360b2394721c019b5d1e75328b09f3',
                  }),
                insertTime: z
                  .preprocess(
                    (val) =>
                      typeof val === 'number' && Number.isSafeInteger(val)
                        ? BigInt(val)
                        : typeof val === 'string' && /^-?\d+$/.test(val)
                          ? BigInt(val)
                          : val,
                    z.int64(),
                  )
                  .openapi({ type: 'integer', format: 'int64', example: 1599621997000 }),
                transferType: z.int32().openapi({ example: 0 }),
                unlockConfirm: z
                  .string()
                  .openapi({ example: '12/12', description: 'confirm times for unlocking' }),
                confirmTimes: z.string().openapi({ example: '12/12' }),
              })
              .openapi({
                required: [
                  'amount',
                  'coin',
                  'network',
                  'status',
                  'address',
                  'addressTag',
                  'txId',
                  'insertTime',
                  'transferType',
                  'unlockConfirm',
                  'confirmTimes',
                ],
              }),
          ),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

export const getSapiV1CapitalWithdrawHistoryRoute = createRoute({
  method: 'get',
  path: '/sapi/v1/capital/withdraw/history',
  tags: ['Wallet'],
  summary: 'Withdraw History (supporting network) (USER_DATA)',
  description:
    "Fetch withdraw history.\n\nThis endpoint specifically uses per second UID rate limit, user's total second level IP rate limit is 180000/second. Response from the endpoint contains header key X-SAPI-USED-UID-WEIGHT-1S, which defines weight used by the current IP.\n\n- `network` may not be in the response for old withdraw.\n- Please notice the default `startTime` and `endTime` to make sure that time interval is within 0-90 days.\n- If both `startTime` and `endTime` are sent, time between `startTime` and `endTime` must be less than 90 days\n- If withdrawOrderId is sent, time between startTime and endTime must be less than 7 days.\n- If withdrawOrderId is sent, startTime and endTime are not sent, will return last 7 days records by default.\n\nWeight(UID): 18000\nRequest Limit: 10 requests per second",
  request: {
    query: z.object({
      coin: OptionalCoinParamsSchema,
      withdrawOrderId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'withdrawOrderId',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      status: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(0).max(6),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'status',
            in: 'query',
            description:
              '* `0` - Email Sent\n* `1` - Cancelled\n* `2` - Awaiting Approval\n* `3` - Rejected\n* `4` - Processing\n* `5` - Failure\n* `6` - Completed',
            schema: { type: 'integer', format: 'int32', minimum: 0, maximum: 6 },
            required: false,
          },
        }),
      startTime: StartTimeParamsSchema,
      endTime: EndTimeParamsSchema,
      offset: OffsetParamsSchema,
      limit: LimitParamsSchema,
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'List of withdraw history',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                address: z
                  .string()
                  .openapi({ example: '0x94df8b352de7f46f64b01d3666bf6e936e44ce60' }),
                amount: z.string().openapi({ example: '8.91000000' }),
                applyTime: z.string().openapi({ example: '2019-10-12 11:12:02' }),
                coin: z.string().openapi({ example: 'USDT' }),
                id: z.string().openapi({ example: 'b6ae22b3aa844210a7041aee7589627c' }),
                withdrawOrderId: z
                  .string()
                  .openapi({
                    example: 'WITHDRAWtest123',
                    description:
                      "will not be returned if there's no withdrawOrderId for this withdraw.",
                  }),
                network: z.string().openapi({ example: 'ETH' }),
                transferType: z
                  .int32()
                  .openapi({
                    example: 0,
                    description: '1 for internal transfer, 0 for external transfer',
                  }),
                status: z.int32().openapi({ example: 6 }),
                transactionFee: z.string().openapi({ example: '0.004' }),
                confirmNo: z.int32().exactOptional().openapi({ example: 3 }),
                info: z
                  .string()
                  .exactOptional()
                  .openapi({
                    example: 'The address is not valid. Please confirm with the recipient',
                    description: 'Reason for withdrawal failure',
                  }),
                txId: z
                  .string()
                  .openapi({
                    example: '0xb5ef8c13b968a406cc62a93a8bd80f9e9a906ef1b3fcf20a2e48573c17659268',
                  }),
              })
              .openapi({
                required: [
                  'address',
                  'amount',
                  'applyTime',
                  'coin',
                  'id',
                  'withdrawOrderId',
                  'network',
                  'transferType',
                  'status',
                  'transactionFee',
                  'txId',
                ],
              }),
          ),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

