export const postSapiV1AssetTransferRoute = createRoute({
  method: 'post',
  path: '/sapi/v1/asset/transfer',
  tags: ['Wallet'],
  summary: 'User Universal Transfer (USER_DATA)',
  description:
    'You need to enable `Permits Universal Transfer` option for the api key which requests this endpoint.\n\n- `fromSymbol` must be sent when type are ISOLATEDMARGIN_MARGIN and ISOLATEDMARGIN_ISOLATEDMARGIN\n- `toSymbol` must be sent when type are MARGIN_ISOLATEDMARGIN and ISOLATEDMARGIN_ISOLATEDMARGIN\n\nENUM of transfer types:\n  - MAIN_UMFUTURE Spot account transfer to USDⓈ-M Futures account\n  - MAIN_CMFUTURE Spot account transfer to COIN-M Futures account\n  - MAIN_MARGIN Spot account transfer to Margin(cross)account\n  - UMFUTURE_MAIN USDⓈ-M Futures account transfer to Spot account\n  - UMFUTURE_MARGIN USDⓈ-M Futures account transfer to Margin(cross)account\n  - CMFUTURE_MAIN COIN-M Futures account transfer to Spot account\n  - CMFUTURE_MARGIN COIN-M Futures account transfer to Margin(cross) account\n  - MARGIN_MAIN Margin(cross)account transfer to Spot account\n  - MARGIN_UMFUTURE Margin(cross)account transfer to USDⓈ-M Futures\n  - MARGIN_CMFUTURE Margin(cross)account transfer to COIN-M Futures\n  - ISOLATEDMARGIN_MARGIN Isolated margin account transfer to Margin(cross) account\n  - MARGIN_ISOLATEDMARGIN Margin(cross) account transfer to Isolated margin account\n  - ISOLATEDMARGIN_ISOLATEDMARGIN Isolated margin account transfer to Isolated margin account\n  - MAIN_FUNDING Spot account transfer to Funding account\n  - FUNDING_MAIN Funding account transfer to Spot account\n  - FUNDING_UMFUTURE Funding account transfer to UMFUTURE account\n  - UMFUTURE_FUNDING UMFUTURE account transfer to Funding account\n  - MARGIN_FUNDING MARGIN account transfer to Funding account\n  - FUNDING_MARGIN Funding account transfer to Margin account\n  - FUNDING_CMFUTURE Funding account transfer to CMFUTURE account\n  - CMFUTURE_FUNDING CMFUTURE account transfer to Funding account\n  - MAIN_OPTION Spot account transfer to Options account\n  - OPTION_MAIN Options account transfer to Spot account\n  - UMFUTURE_OPTION USDⓈ-M Futures account transfer to Options account\n  - OPTION_UMFUTURE Options account transfer to USDⓈ-M Futures account\n  - MARGIN_OPTION Margin(cross)account transfer to Options account\n  - OPTION_MARGIN Options account transfer to Margin(cross)account\n  - FUNDING_OPTION Funding account transfer to Options account\n  - OPTION_FUNDING Options account transfer to Funding account\n  - MAIN_PORTFOLIO_MARGIN Spot account transfer to Portfolio Margin account\n  - PORTFOLIO_MARGIN_MAIN Portfolio Margin account transfer to Spot account\n  - MAIN_ISOLATED_MARGIN Spot account transfer to Isolated margin account\n  - ISOLATED_MARGIN_MAIN Isolated margin account transfer to Spot account\n\nWeight(IP): 1',
  request: {
    query: z.object({
      type: UnivTransferTypeParamsSchema,
      asset: AssetParamsSchema,
      amount: AmountParamsSchema,
      fromSymbol: FromSymbolParamsSchema,
      toSymbol: ToSymbolParamsSchema,
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Transfer id',
      content: {
        'application/json': {
          schema: z
            .object({
              tranId: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({ type: 'integer', format: 'int64', example: 13526853623 }),
            })
            .openapi({ required: ['tranId'] }),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

