export const postSapiV1SubAccountFuturesTransferRoute = createRoute({
  method: 'post',
  path: '/sapi/v1/sub-account/futures/transfer',
  tags: ['Sub-Account'],
  summary: 'Transfer for Sub-account (For Master Account)',
  description: 'Weight(IP): 1',
  request: {
    query: z.object({
      email: SubAccountEmailParamsSchema,
      asset: AssetParamsSchema,
      amount: AmountParamsSchema,
      type: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().min(1).max(4),
        )
        .openapi({
          param: {
            name: 'type',
            in: 'query',
            description:
              "* `1` - transfer from subaccount's spot account to its USDT-margined futures account\n* `2` - transfer from subaccount's USDT-margined futures account to its spot account\n* `3` - transfer from subaccount's spot account to its COIN-margined futures account\n* `4` - transfer from subaccount's COIN-margined futures account to its spot account",
            required: true,
            schema: { type: 'integer', format: 'int32', minimum: 1, maximum: 4 },
          },
        }),
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Transfer id',
      content: {
        'application/json': {
          schema: z
            .object({ txnId: z.string().openapi({ example: '2966662589' }) })
            .openapi({ required: ['txnId'] }),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

