export const getSapiV1SubAccountTransferSubUserHistoryRoute = createRoute({
  method: 'get',
  path: '/sapi/v1/sub-account/transfer/subUserHistory',
  tags: ['Sub-Account'],
  summary: 'Sub-account Transfer History (For Sub-account)',
  description:
    '- If `type` is not sent, the records of type 2: transfer out will be returned by default.\n- If `startTime` and `endTime` are not sent, the recent 30-day data will be returned.\n\nWeight(IP): 1',
  request: {
    query: z.object({
      asset: OptionalAssetParamsSchema,
      type: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'type',
            in: 'query',
            description: '* `1` - transfer in\n* `2` - transfer out',
            schema: { type: 'integer', format: 'int32' },
            required: false,
          },
        }),
      startTime: StartTimeParamsSchema,
      endTime: EndTimeParamsSchema,
      limit: LimitParamsSchema,
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Transfer id',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                counterParty: z.string().openapi({ example: 'master' }),
                email: z.string().openapi({ example: 'master@test.com' }),
                type: z
                  .int32()
                  .openapi({ example: 1, description: '1 for transfer in, 2 for transfer out' }),
                asset: z.string().openapi({ example: 'BTC' }),
                qty: z.string().openapi({ example: '1' }),
                fromAccountType: z.string().openapi({ example: 'SPOT' }),
                toAccountType: z.string().openapi({ example: 'SPOT' }),
                status: z.string().openapi({ example: 'SUCCESS' }),
                tranId: z
                  .preprocess(
                    (val) =>
                      typeof val === 'number' && Number.isSafeInteger(val)
                        ? BigInt(val)
                        : typeof val === 'string' && /^-?\d+$/.test(val)
                          ? BigInt(val)
                          : val,
                    z.int64(),
                  )
                  .openapi({ type: 'integer', format: 'int64', example: 11798835829 }),
                time: z
                  .preprocess(
                    (val) =>
                      typeof val === 'number' && Number.isSafeInteger(val)
                        ? BigInt(val)
                        : typeof val === 'string' && /^-?\d+$/.test(val)
                          ? BigInt(val)
                          : val,
                    z.int64(),
                  )
                  .openapi({ type: 'integer', format: 'int64', example: 1544433325000 }),
              })
              .openapi({
                required: [
                  'counterParty',
                  'email',
                  'type',
                  'asset',
                  'qty',
                  'fromAccountType',
                  'toAccountType',
                  'status',
                  'tranId',
                  'time',
                ],
              }),
          ),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

