export const postSapiV1FuturesTransferRoute = createRoute({
  method: 'post',
  path: '/sapi/v1/futures/transfer',
  tags: ['Futures'],
  summary: 'New Future Account Transfer (USER_DATA)',
  description: 'Execute transfer between spot account and futures account.\n\nWeight(IP): 1',
  request: {
    query: z.object({
      asset: AssetParamsSchema,
      amount: AmountParamsSchema,
      type: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'type',
            in: 'query',
            required: true,
            description:
              '1: transfer from spot account to USDT-Ⓜ futures account. 2: transfer from USDT-Ⓜ futures account to spot account. 3: transfer from spot account to COIN-Ⓜ futures account. 4: transfer from COIN-Ⓜ futures account to spot account.',
            schema: { type: 'integer', format: 'int64' },
          },
        }),
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Futures Transfer',
      content: {
        'application/json': {
          schema: z
            .object({
              tranId: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({ type: 'integer', format: 'int64', example: 100000001 }),
            })
            .openapi({ required: ['tranId'] }),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

