export const postSapiV1AlgoFuturesNewOrderVpRoute = createRoute({
  method: 'post',
  path: '/sapi/v1/algo/futures/newOrderVp',
  tags: ['Futures Algo'],
  summary: 'Volume Participation(VP) New Order (TRADE)',
  description:
    'Send in a VP new order. Only support on USDⓈ-M Contracts.\n\n- You need to enable `Futures Trading Permission` for the api key which requests this endpoint.\n- Base URL: https://api.binance.com\n\n- Total Algo open orders max allowed: 10 orders.\n- Leverage of symbols and position mode will be the same as your futures account settings. You can set up through the trading page or fapi.\n- Receiving "success": true does not mean that your order will be executed. Please use the query order endpoints(GET sapi/v1/algo/futures/openOrders or GET sapi/v1/algo/futures/historicalOrders) to check the order status. For example: Your futures balance is insufficient, or open position with reduce only or position side is inconsistent with your own setting. In these cases you will receive "success": true, but the order status will be expired after we check it.\n\nWeight(UID): 3000',
  request: {
    query: z.object({
      symbol: SymbolParamsSchema,
      side: SideParamsSchema,
      positionSide: PositionSideParamsSchema,
      quantity: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.float64(),
        )
        .openapi({
          param: {
            name: 'quantity',
            in: 'query',
            required: true,
            description:
              'Quantity of base asset; The notional (quantity * mark price(base asset)) must be more than the equivalent of 10,000 USDT and less than the equivalent of 1,000,000 USDT',
            schema: { type: 'number', format: 'double' },
          },
        }),
      urgency: z
        .enum(['LOW', 'MEDIUM', 'HIGH'])
        .openapi({
          param: {
            name: 'urgency',
            in: 'query',
            description:
              'Represent the relative speed of the current execution; ENUM: LOW, MEDIUM, HIGH',
            required: true,
            schema: { type: 'string', enum: ['LOW', 'MEDIUM', 'HIGH'], example: 'LOW' },
          },
          example: 'LOW',
        }),
      clientAlgoId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'clientAlgoId',
            in: 'query',
            description:
              'A unique id among Algo orders (length should be 32 characters)， If it is not sent, we will give default value',
            schema: { type: 'string', example: '00358ce6a268403398bd34eaa36dffe7' },
            required: false,
          },
          example: '00358ce6a268403398bd34eaa36dffe7',
        }),
      reduceOnly: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'reduceOnly',
            in: 'query',
            description:
              "'true' or 'false'. Default 'false'; Cannot be sent in Hedge Mode; Cannot be sent when you open a position",
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      limitPrice: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.float64(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limitPrice',
            in: 'query',
            description:
              'Limit price of the order; If it is not sent, will place order by market price by default',
            schema: { type: 'number', format: 'double' },
            required: false,
          },
        }),
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Volume Participation(VP) Order',
      content: {
        'application/json': {
          schema: z
            .object({
              clientAlgoId: z.string().openapi({ example: '00358ce6a268403398bd34eaa36dffe7' }),
              success: z.boolean().openapi({ example: true }),
              code: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({ type: 'integer', format: 'int64', example: 0 }),
              msg: z.string().openapi({ example: 'OK' }),
            })
            .openapi({ required: ['clientAlgoId', 'success', 'code', 'msg'] }),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

