export const getSapiV1AlgoSpotSubOrdersRoute = createRoute({
  method: 'get',
  path: '/sapi/v1/algo/spot/subOrders',
  tags: ['Spot Algo'],
  summary: 'Query Sub Orders',
  description: 'Get respective sub orders for a specified algoId\n\nWeight(IP): 1',
  request: {
    query: z.object({
      algoId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'algoId',
            in: 'query',
            required: true,
            schema: { type: 'integer', format: 'int64' },
          },
        }),
      page: PageParamsSchema,
      pageSize: SmallPageSizeParamsSchema,
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'twap sub orders',
      content: {
        'application/json': {
          schema: z
            .object({
              total: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .openapi({ type: 'integer', format: 'int64', example: 1 }),
              executedQty: z.string().openapi({ example: '1.000' }),
              executedAmt: z.string().openapi({ example: '3229.44000000' }),
              subOrders: z.array(
                z
                  .object({
                    algoId: z.int().openapi({ example: 14517 }),
                    orderId: z
                      .preprocess(
                        (val) =>
                          typeof val === 'number' && Number.isSafeInteger(val)
                            ? BigInt(val)
                            : typeof val === 'string' && /^-?\d+$/.test(val)
                              ? BigInt(val)
                              : val,
                        z.int64(),
                      )
                      .openapi({ type: 'integer', format: 'int64', example: 8389765519993909000 }),
                    orderStatus: z.string().openapi({ example: 'FILLED' }),
                    executedQty: z.string().openapi({ example: '0.000' }),
                    executedAmt: z.string().openapi({ example: '0.000' }),
                    feeAmt: z.string().openapi({ example: '-1.61471999' }),
                    feeAsset: z.string().openapi({ example: 'USDT' }),
                    bookTime: z
                      .preprocess(
                        (val) =>
                          typeof val === 'number' && Number.isSafeInteger(val)
                            ? BigInt(val)
                            : typeof val === 'string' && /^-?\d+$/.test(val)
                              ? BigInt(val)
                              : val,
                        z.int64(),
                      )
                      .openapi({ type: 'integer', format: 'int64', example: 1649319001964 }),
                    avgPrice: z.string().openapi({ example: '3229.44' }),
                    side: z.string().openapi({ example: 'SELL' }),
                    symbol: z.string().openapi({ example: 'ETHUSDT' }),
                    subId: z.int().openapi({ example: 1 }),
                    timeInForce: z.string().openapi({ example: 'IMMEDIATE_OR_CANCEL' }),
                    origQty: z.string().openapi({ example: '1.000' }),
                  })
                  .openapi({
                    required: [
                      'algoId',
                      'orderId',
                      'orderStatus',
                      'executedQty',
                      'executedAmt',
                      'feeAmt',
                      'feeAsset',
                      'bookTime',
                      'avgPrice',
                      'side',
                      'symbol',
                      'subId',
                      'timeInForce',
                      'origQty',
                    ],
                  }),
              ),
            })
            .openapi({ required: ['total', 'executedQty', 'executedAmt', 'subOrders'] }),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

