export const getSapiV1LoanVipCollateralAccountRoute = createRoute({
  method: 'get',
  path: '/sapi/v1/loan/vip/collateral/account',
  tags: ['VIP Loans'],
  summary: 'Check Locked Value of VIP Collateral Account (USER_DATA)',
  description: 'VIP loan is available for VIP users only.\n\nWeight(IP): 6000',
  request: {
    query: z.object({
      orderId: OrderIdParamsSchema,
      collateralAccountId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'collateralAccountId',
            in: 'query',
            required: false,
            schema: { type: 'integer', format: 'int64' },
          },
        }),
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'VIP Locked Value',
      content: {
        'application/json': {
          schema: z
            .object({
              rows: z.array(
                z
                  .object({
                    collateralAccountId: z.string().openapi({ example: '12345678' }),
                    collateralCoin: z.string().openapi({ example: 'BNB,BTC,ETH' }),
                    collateralValue: z
                      .string()
                      .openapi({
                        example: '500.27565492',
                        description: 'locked collateral value shown in USD value',
                      }),
                  })
                  .openapi({
                    required: ['collateralAccountId', 'collateralCoin', 'collateralValue'],
                  }),
              ),
              total: z.int32().openapi({ example: 1 }),
            })
            .openapi({ required: ['rows', 'total'] }),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

