export const postSapiV1LoanCustomizeMarginCallRoute = createRoute({
  method: 'post',
  path: '/sapi/v1/loan/customize/margin_call',
  tags: ['Crypto Loans'],
  summary: 'Crypto Loan Customize Margin Call (TRADE)',
  description: 'Customize margin call for ongoing orders only.\n\nWeight(UID): 6000',
  request: {
    query: z.object({
      orderId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'orderId',
            in: 'query',
            required: false,
            description:
              'Mandatory when collateralCoin is empty. Send either orderId or collateralCoin, if both parameters are sent, take orderId only.',
            schema: { type: 'integer', format: 'int64' },
          },
        }),
      collateralCoin: CollateralCoinParamsSchema,
      marginCall: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.float32(),
        )
        .openapi({
          param: {
            name: 'marginCall',
            in: 'query',
            required: true,
            schema: { type: 'number', format: 'float' },
          },
        }),
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Collateral Assets Data',
      content: {
        'application/json': {
          schema: z
            .object({
              rows: z.array(
                z
                  .object({
                    orderId: z.string().openapi({ example: '100000001' }),
                    collateralCoin: z.string().openapi({ example: 'BNB' }),
                    preMarginCall: z.string().openapi({ example: '0.8' }),
                    afterMarginCall: z.string().openapi({ example: '0.7' }),
                    customizeTime: z
                      .preprocess(
                        (val) =>
                          typeof val === 'number' && Number.isSafeInteger(val)
                            ? BigInt(val)
                            : typeof val === 'string' && /^-?\d+$/.test(val)
                              ? BigInt(val)
                              : val,
                        z.int64(),
                      )
                      .openapi({ type: 'integer', format: 'int64', example: 1575018510000 }),
                  })
                  .openapi({
                    required: [
                      'orderId',
                      'collateralCoin',
                      'preMarginCall',
                      'afterMarginCall',
                      'customizeTime',
                    ],
                  }),
              ),
              total: z.int32().openapi({ example: 1 }),
            })
            .openapi({ required: ['rows', 'total'] }),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

