export const getSapiV1PayTransactionsRoute = createRoute({
  method: 'get',
  path: '/sapi/v1/pay/transactions',
  tags: ['Pay'],
  summary: 'Get Pay Trade History (USER_DATA)',
  description:
    "- If startTime and endTime are not sent, the recent 90 days' data will be returned.\n- The max interval between startTime and endTime is 90 days.\n- Support for querying orders within the last 18 months.\n\nWeight(UID): 3000",
  request: {
    query: z.object({
      startTime: StartTimeParamsSchema,
      endTime: EndTimeParamsSchema,
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'default 100, max 100',
            schema: { type: 'integer', format: 'int32', example: 100 },
            required: false,
          },
          example: 100,
        }),
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Pay History',
      content: {
        'application/json': {
          schema: z
            .object({
              code: z.string().openapi({ example: '000000' }),
              message: z.string().openapi({ example: 'success' }),
              data: z.array(
                z
                  .object({
                    orderType: z
                      .string()
                      .openapi({
                        example: 'C2C',
                        description:
                          'Enum：PAY(C2B Merchant Acquiring Payment), PAY_REFUND(C2B Merchant Acquiring Payment,refund), C2C(C2C Transfer Payment),CRYPTO_BOX(Crypto box), CRYPTO_BOX_RF(Crypto Box, refund), C2C_HOLDING(Transfer to new Binance user), C2C_HOLDING_RF(Transfer to new Binance user,refund), PAYOUT(B2C Disbursement Payment)',
                      }),
                    transactionId: z.string().openapi({ example: 'M_P_71505104267788288' }),
                    transactionTime: z
                      .preprocess(
                        (val) =>
                          typeof val === 'number' && Number.isSafeInteger(val)
                            ? BigInt(val)
                            : typeof val === 'string' && /^-?\d+$/.test(val)
                              ? BigInt(val)
                              : val,
                        z.int64(),
                      )
                      .openapi({ type: 'integer', format: 'int64', example: 1610090460133 }),
                    amount: z
                      .string()
                      .openapi({
                        example: '23.72469206',
                        description:
                          'order amount(up to 8 decimal places), positive is income, negative is expenditure',
                      }),
                    currency: z.string().openapi({ example: 'BNB' }),
                    walletType: z.int().openapi({ example: 1 }),
                    walletTypes: z.array(z.int()),
                    fundsDetail: z.array(
                      z.object({ currency: z.string(), amount: z.string() }).openapi({
                        example: [
                          { currency: 'USDT', amount: '1.2' },
                          { currency: 'ETH', amount: '0.0001' },
                        ],
                        required: ['currency', 'amount'],
                      }),
                    ),
                    payerInfo: z
                      .object({
                        name: z.string().openapi({ example: 'Jack' }),
                        type: z.string().openapi({ example: 'USER' }),
                        binanceId: z.string().openapi({ example: '12345678' }),
                        accountId: z.string().openapi({ example: '67736251' }),
                      })
                      .openapi({ required: ['name', 'type', 'binanceId', 'accountId'] }),
                    receiverInfo: z
                      .object({
                        name: z.string().openapi({ example: 'Alan' }),
                        type: z.string().openapi({ example: 'MERCHANT' }),
                        email: z.string().openapi({ example: 'alan@test.com' }),
                        binanceId: z.string().openapi({ example: '34355667' }),
                        accountId: z.string().openapi({ example: '21326891' }),
                        countryCode: z.string().openapi({ example: '1' }),
                        phoneNumber: z.string().openapi({ example: '8057651210' }),
                        mobileCode: z.string().openapi({ example: 'US' }),
                        extend: z
                          .array(
                            z
                              .object({
                                institutionName: z.string(),
                                cardNumber: z.string(),
                                digitalWalletId: z.string(),
                              })
                              .openapi({
                                required: ['institutionName', 'cardNumber', 'digitalWalletId'],
                              }),
                          )
                          .exactOptional(),
                      })
                      .openapi({
                        required: [
                          'name',
                          'type',
                          'email',
                          'binanceId',
                          'accountId',
                          'countryCode',
                          'phoneNumber',
                          'mobileCode',
                        ],
                      }),
                  })
                  .openapi({
                    required: [
                      'orderType',
                      'transactionId',
                      'transactionTime',
                      'amount',
                      'currency',
                      'walletType',
                      'walletTypes',
                      'fundsDetail',
                      'payerInfo',
                      'receiverInfo',
                    ],
                  }),
              ),
              success: z.boolean(),
            })
            .openapi({ required: ['code', 'message', 'data', 'success'] }),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

