export const postSapiV1GiftcardCreateCodeRoute = createRoute({
  method: 'post',
  path: '/sapi/v1/giftcard/createCode',
  tags: ['Gift Card'],
  summary: 'Create a Binance Code (USER_DATA)',
  description:
    'This API is for creating a Binance Code. To get started with, please make sure:\n\n- You have a Binance account\n- You have passed kyc\n- You have a sufficient balance in your Binance funding wallet\n- You need Enable Withdrawals for the API Key which requests this endpoint.\n\nDaily creation volume: 2 BTC / 24H Daily creation times: 200 Codes / 24H\n\nWeight(IP): 1',
  request: {
    query: z.object({
      token: z
        .string()
        .openapi({
          param: {
            name: 'token',
            in: 'query',
            description: 'The coin type contained in the Binance Code',
            required: true,
            schema: { type: 'string' },
          },
        }),
      amount: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.float64(),
        )
        .openapi({
          param: {
            name: 'amount',
            in: 'query',
            required: true,
            description: 'The amount of the coin',
            schema: { type: 'number', format: 'double' },
          },
        }),
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Code creation',
      content: {
        'application/json': {
          schema: z
            .object({
              code: z.string().openapi({ example: '000000' }),
              message: z.string().openapi({ example: 'success' }),
              data: z
                .object({
                  referenceNo: z.string().openapi({ example: '0033002327977405' }),
                  code: z.string().openapi({ example: 'AOGANK3NB4GIT3C6' }),
                  expiredTime: z
                    .preprocess(
                      (val) =>
                        typeof val === 'number' && Number.isSafeInteger(val)
                          ? BigInt(val)
                          : typeof val === 'string' && /^-?\d+$/.test(val)
                            ? BigInt(val)
                            : val,
                      z.int64(),
                    )
                    .openapi({ type: 'integer', format: 'int64', example: 1727417154000 }),
                })
                .openapi({ required: ['referenceNo', 'code', 'expiredTime'] }),
              success: z.boolean(),
            })
            .openapi({ required: ['code', 'message', 'data', 'success'] }),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

