export const getSapiV1LendingAutoInvestRedeemHistoryRoute = createRoute({
  method: 'get',
  path: '/sapi/v1/lending/auto-invest/redeem/history',
  tags: ['Auto-Invest'],
  summary: 'Index Linked Plan Redemption History (USER_DATA)',
  description:
    'Get the history of Index Linked Plan Redemption transactions\n\nMax 30 day difference between startTime and endTime\nIf no startTime and endTime, default to show past 30 day records\n\nWeight(IP): 1',
  request: {
    query: z.object({
      requestId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'requestId',
            in: 'query',
            required: true,
            schema: { type: 'integer', format: 'int64', example: 12345 },
          },
          example: 12345,
        }),
      startTime: StartTimeParamsSchema,
      endTime: EndTimeParamsSchema,
      current: CurrentParamsSchema,
      asset: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'asset',
            in: 'query',
            schema: { type: 'string', example: 'BTC' },
            required: false,
          },
          example: 'BTC',
        }),
      size: SizeParamsSchema,
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Redemption history',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                indexId: z
                  .preprocess(
                    (val) =>
                      typeof val === 'number' && Number.isSafeInteger(val)
                        ? BigInt(val)
                        : typeof val === 'string' && /^-?\d+$/.test(val)
                          ? BigInt(val)
                          : val,
                    z.int64(),
                  )
                  .openapi({ type: 'integer', format: 'int64', example: 1 }),
                indexName: z.string().openapi({ example: 'BINANCE TOP 10 EW' }),
                redemptionId: z
                  .preprocess(
                    (val) =>
                      typeof val === 'number' && Number.isSafeInteger(val)
                        ? BigInt(val)
                        : typeof val === 'string' && /^-?\d+$/.test(val)
                          ? BigInt(val)
                          : val,
                    z.int64(),
                  )
                  .openapi({ type: 'integer', format: 'int64', example: 11 }),
                status: z.string().openapi({ example: 'SUCCESS' }),
                asset: z.string().openapi({ example: 'BTC' }),
                amount: z.string().openapi({ example: '0.005' }),
                redemptionDateTime: z
                  .preprocess(
                    (val) =>
                      typeof val === 'number' && Number.isSafeInteger(val)
                        ? BigInt(val)
                        : typeof val === 'string' && /^-?\d+$/.test(val)
                          ? BigInt(val)
                          : val,
                    z.int64(),
                  )
                  .openapi({ type: 'integer', format: 'int64', example: 1648378800000 }),
                transactionFee: z.string().openapi({ example: '0' }),
                transactionFeeUnit: z.string().openapi({ example: 'USDT' }),
              })
              .openapi({
                required: [
                  'indexId',
                  'indexName',
                  'redemptionId',
                  'status',
                  'asset',
                  'amount',
                  'redemptionDateTime',
                  'transactionFee',
                  'transactionFeeUnit',
                ],
              }),
          ),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})

