export const postSapiV1DciProductAutoCompoundEditStatusRoute = createRoute({
  method: 'post',
  path: '/sapi/v1/dci/product/auto_compound/edit-status',
  tags: ['Dual Investment'],
  summary: 'Change Auto-Compound status(USER_DATA)',
  description:
    'Change Auto-Compound status\n\n- 15:31 ~ 16:00 UTC+8 This function is disabled\n\nWeight(IP): 1\n\nRate Limit: Maximum 1 time/s per account',
  request: {
    query: z.object({
      positionId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            name: 'positionId',
            in: 'query',
            required: true,
            description: 'Get positionId from /sapi/v1/dci/product/positions',
            schema: { type: 'integer', format: 'int64' },
          },
        }),
      autoCompoundPlan: AutoCompoundPlanParamsSchema,
      recvWindow: RecvWindowParamsSchema,
      timestamp: TimestampParamsSchema,
      signature: SignatureParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Change Auto-Compound status response',
      content: {
        'application/json': {
          schema: z
            .object({
              positionId: z.string().openapi({ example: 123456789 }),
              autoCompoundPlan: z
                .string()
                .openapi({ description: 'NONE, STANDARD, ADVANCED', example: 'ADVANCED' }),
            })
            .openapi({ required: ['positionId', 'autoCompoundPlan'] }),
        },
      },
    },
    400: { description: 'Bad Request', content: { 'application/json': { schema: ErrorSchema } } },
    401: {
      description: 'Unauthorized Request',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
  security: [{ ApiKeyAuth: [] }],
})
